<div class="sn-wrap sn-cart"><section><span class="sn-eyebrow">Your selection</span><h1 class="sn-title" style="margin:10px 0 20px">Your bag.</h1>@if(session('cart_status'))<p class="sn-alert" role="status">{{ session('cart_status') }}</p>@endif
