@foreach($cart->items as $item)<div class="sn-cart-item">@if(data_get($item->variant->product->media, '0'))<img src="{{ data_get($item->variant->product->media, '0') }}" alt="{{ $item->variant->product->title }}">@endif<div style="flex:1"><h3><a href="{{ route('managed-website.store.products.show', ['handle' => $item->variant->product->handle]) }}">{{ $item->variant->product->title }}</a></h3><p>${{ number_format($item->variant->price_cents/100,2) }} each</p><form method="POST" action="{{ route('managed-website.store.cart.lines.update', ['item' => $item->id]) }}" style="display:flex;align-items:center;gap:8px;margin-top:10px">@csrf<label class="sn-label" for="qty-{{ $item->id }}" style="margin:0">Qty</label><input class="sn-input" style="width:65px;padding:8px" id="qty-{{ $item->id }}" type="number" min="0" max="20" name="quantity" value="{{ $item->quantity }}"><button type="submit" style="border:0;background:transparent;text-decoration:underline;cursor:pointer;font-size:12px">Update</button></form></div><strong>${{ number_format($item->quantity*$item->variant->price_cents/100,2) }}</strong></div>@endforeach<a href="{{ route('managed-website.store.index') }}" style="display:inline-block;margin:24px 0;text-decoration:underline;font-size:13px">← Continue shopping</a>@endif</section>@if($cart->items->isNotEmpty())<aside class="sn-summary"><h2>Order summary</h2><div class="sn-summary-row"><span>Subtotal</span><strong>${{ number_format($subtotal/100,2) }}</strong></div><div class="sn-summary-row"><span>Shipping</span><span>{{ $subtotal >= 5000 ? 'Free over $49.99' : 'Calculated next' }}</span></div><hr class="sn-divider"><div class="sn-summary-row"><strong>Estimated total</strong><strong>${{ number_format($subtotal/100,2) }}</strong></div><p class="sn-note">Taxes and final total are calculated at secure checkout.</p><div style="border-top:1px solid #d9ded6;margin:22px 0 0;padding-top:20px"><p class="sn-eyebrow" style="margin:0 0 8px">Express checkout preview</p><button type="button" disabled style="width:100%;border:1px solid #b9a9ce;background:#eee7f4;color:#4a315e;padding:13px;font-weight:800;cursor:not-allowed">Shop Pay · planned</button><p class="sn-note">Shop Pay Wallet can be connected after Sawyer’s Shopify merchant setup and payment approval. This preview does not take payment.</p></div>@if(!$shippingEnabled || !$checkoutReady)<p class="sn-alert" role="status">Checkout setup is in progress. Your bag is ready to explore, and shipping and payment will open after merchant account checks are complete.</p>@else<form method="POST" action="{{ route('managed-website.store.checkout') }}" id="sn-checkout">@csrf<input type="hidden" name="fulfillment_method" value="ship"><label class="sn-label" for="customer-name">Full name</label><input required class="sn-input" id="customer-name" name="name" autocomplete="name"><label class="sn-label" for="customer-email">Email</label><input required class="sn-input" id="customer-email" name="email" type="email" autocomplete="email"><label class="sn-label" for="customer-phone">Phone (optional)</label><input class="sn-input" id="customer-phone" name="phone" autocomplete="tel"><h3 style="font:500 23px var(--serif);margin:26px 0 5px">Shipping address</h3><div class="sn-ship-fields"><input type="hidden" name="shipping_address[name]" id="ship-name"><label class="wide"><span class="sn-label">Street address</span><input required class="sn-input" name="shipping_address[street1]" autocomplete="address-line1"></label><label class="wide"><span class="sn-label">Apartment / suite</span><input class="sn-input" name="shipping_address[street2]" autocomplete="address-line2"></label><label class="wide"><span class="sn-label">City</span><input required class="sn-input" name="shipping_address[city]" autocomplete="address-level2"></label><label><span class="sn-label">State</span><input required class="sn-input" name="shipping_address[state]" maxlength="2" autocomplete="address-level1"></label><label><span class="sn-label">ZIP code</span><input required class="sn-input" name="shipping_address[zip]" autocomplete="postal-code"></label><input type="hidden" name="shipping_address[country]" value="US"></div><button class="sn-btn sn-btn-light" type="button" id="sn-rates" style="width:100%;margin-top:20px">Find shipping options</button><div id="sn-rate-results" role="status" aria-live="polite"></div><button class="sn-btn" id="sn-pay" type="submit" disabled style="margin-top:18px">Continue to secure payment</button></form><script>document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('sn-checkout'),button=document.getElementById('sn-rates'),results=document.getElementById('sn-rate-results'),pay=document.getElementById('sn-pay');if(!form)return;button.addEventListener('click',async()=>{document.getElementById('ship-name').value=document.getElementById('customer-name').value;const address={};for(const input of form.querySelectorAll('[name^="shipping_address["]')){address[input.name.slice(17,-1)]=input.value}results.textContent='Finding shipping options…';pay.disabled=true;try{const response=await fetch(@json(route('managed-website.store.shipping-rates')),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':form.querySelector('[name="_token"]').value},body:JSON.stringify({shipping_address:address})});const data=await response.json();if(!response.ok)throw new Error(data.message||'No shipping options are available for that address.');results.innerHTML='';for(const quote of data.quotes){const label=document.createElement('label');label.className='sn-alert';label.style.display='block';const radio=document.createElement('input');radio.type='radio';radio.name='shipping_rate_quote_id';radio.value=quote.id;radio.addEventListener('change',()=>{pay.disabled=false});label.append(radio,document.createTextNode(' '+quote.carrier+' · '+quote.service+' · '+(Number(@json($subtotal))>=5000?'Free shipping':'$'+(quote.amount_cents/100).toFixed(2))));results.append(label)}}catch(error){results.textContent=error.message}});form.addEventListener('submit',event=>{document.getElementById('ship-name').value=document.getElementById('customer-name').value;if(!form.querySelector('[name="shipping_rate_quote_id"]:checked'))event.preventDefault()})});</script>@endif</aside>@endif</div>
